---@class UISystemGuideDialogNode
local UISystemGuideDialogNode = Class("UISystemGuideDialogNode")

function UISystemGuideDialogNode:__init()
end

function UISystemGuideDialogNode:__delete()
    self.context = nil
end

---Execute
---@param moduleStepVo SystemGuideModuleStepVo
function UISystemGuideDialogNode:Execute(moduleStepVo)
    local dialogType = moduleStepVo.dialogType
    if dialogType == Constants.GuideDialogType.Mask then
        self:ShowDialogNode(moduleStepVo)
    elseif dialogType == Constants.GuideDialogType.NoMask then
        Events.Broadcast(Constants.EventNames.MainHomeCameraAnimatorReset)

        self:ShowDialogTipsBoard(moduleStepVo)
    end

    self:PlaySe(moduleStepVo.voice)
end


