---ShowDialogNode
---@param moduleStepVo SystemGuideModuleStepVo
function UISystemGuideDialogNode:ShowDialogNode(moduleStepVo)
    ---没有多文本
    --- 对话文本使用 || 分割
    local text                = moduleStepVo.text
    --- 对话节点位置 使用 || 分割
    local dialogPos           = moduleStepVo.dialogPos
    --- 对话框线方向 
    local dialogLineDirection = moduleStepVo.dialogLineDirection
    local renderCameraType        = moduleStepVo.renderCameraType
    
    --- 刷新对话框
    local context        = self.context
    context:FreshDialogNode(text, dialogPos, dialogLineDirection, renderCameraType)


end

