---PlaySe
---播放音频
---@param vo CardSkinVo 
function UISystemGuideDialogNode:PlaySe(soundId)
    if string.isEmpty(soundId) then return end
    print("guide---->>>>>>> soundId", soundId)
    CriWareUtils.PlaySeById(soundId)
    self.soundId = soundId

end
function UISystemGuideDialogNode:StopSe()
    local soundId = self.soundId
    if string.isEmpty(soundId) then return end

    CriWareUtils.StopById(soundId)
    self.soundId = nil

end



function UISystemGuideDialogNode:Clear()
    if self.isShowTipsBoard then
        local node = UIModule.RootCanvas.transform:Find("UISystemGuideTipsBoard")
        if not isNull(node) then
            KTool.SafeDelete(node.gameObject, true)
        end
    end

    self:StopSe()
end


return UISystemGuideDialogNode